import re, os

# Extract citation keys from tex files
cited = set()
for root, dirs, files in os.walk('paper/sections'):
    for f in files:
        if f.endswith('.tex'):
            with open(os.path.join(root, f)) as fh:
                text = fh.read()
            for m in re.finditer(r'\\\\cite[tp]?\{([^}]+)\}', text):
                for key in m.group(1).split(','):
                    cited.add(key.strip())

with open('paper/main.tex') as fh:
    text = fh.read()
for m in re.finditer(r'\\\\cite[tp]?\{([^}]+)\}', text):
    for key in m.group(1).split(','):
        cited.add(key.strip())

# Extract bib keys
bib_keys = set()
with open('paper/references.bib') as fh:
    for m in re.finditer(r'@\w+\{(\w+)', fh.read()):
        bib_keys.add(m.group(1))

print(f'Cited in text: {len(cited)}')
print(f'Bib entries: {len(bib_keys)}')
print()
missing = cited - bib_keys
orphans = bib_keys - cited
if missing:
    print('MISSING from .bib (cited but no entry):')
    for k in sorted(missing): print(f'  - {k}')
else:
    print('No missing entries (all citations have bib entries)')
print()
if orphans:
    print('ORPHAN bib entries (not cited in text):')
    for k in sorted(orphans): print(f'  - {k}')
else:
    print('No orphan entries')
"
